define(['jquery'],function($){const activate=(root,id)=>{root.querySelectorAll('[data-tab-target]').forEach((button)=>{const active=button.dataset.tabTarget===id;button.classList.toggle('is-active',active);button.setAttribute('aria-selected',active?'true':'false');button.tabIndex=active?0:-1;});root.querySelectorAll('[data-tab-panel]').forEach((panel)=>{panel.classList.toggle('d-none',panel.dataset.tabPanel!==id);});};const init=()=>{$('[data-region="lesson-tabs"]').each(function(){const root=this;const buttons=[...root.querySelectorAll('[data-tab-target]')];buttons.forEach((button,index)=>{button.addEventListener('click',()=>activate(root,button.dataset.tabTarget));button.addEventListener('keydown',(event)=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){return;}event.preventDefault();let target=index;if(event.key==='ArrowLeft'){target=(index-1+buttons.length)%buttons.length;}else if(event.key==='ArrowRight'){target=(index+1)%buttons.length;}else if(event.key==='Home'){target=0;}else if(event.key==='End'){target=buttons.length-1;}activate(root,buttons[target].dataset.tabTarget);buttons[target].focus();});});});};return{init:init};});
